// ===========================================================================
// MOMENTS — entry point, mood/need based, in Portuguese
// ===========================================================================
const MOMENTS = [
  { id: "cafe", emoji: "☕", label: "Hmm... isso aqui com um café..." },
  { id: "dia-dificil", emoji: "💛", label: "Dias de luta. Doces de glória." },
  { id: "freezer", emoji: "❄️", label: "Seu eu do futuro agradece." },
  { id: "presente", emoji: "🎁", label: "É só uma lembrancinha." },
  { id: "festa", emoji: "🎉", label: "Não vai ter festa... só um bolinho." },
];

const MOMENT_INTRO = {
  cafe: "Sempre tem um bom motivo para colocar um docinho na mesa.",
  "dia-dificil": "Seja TPM, segunda-feira ou um dia difícil. Nem todo problema tem solução, mas um docinho sempre ajuda.",
  freezer: "Guarde no freezer e tenha sempre à mão opções low sugar para a lancheira das crianças ou para aquela vontade de um doce de última hora.",
  presente: "Pra gente, é muito mais que isso. Cada caixa é única, pensada e personalizada para que quem a receba se sinta realmente especial.",
  festa: "A gente conhece essa história... foi assim que muita festa começou.",
};

const MOMENT_ORDER = {
  "dia-dificil": ["bala-de-coco", "chocobomb", "cone-trufado", "mini-donut-decorado"],
};

function pickForMoment(momentId) {
  const matched = PRODUCTS.filter((p) => p.moments.includes(momentId));
  const priority = MOMENT_ORDER[momentId];
  if (!priority) return matched;
  return [...matched].sort((a, b) => {
    const ia = priority.indexOf(a.id);
    const ib = priority.indexOf(b.id);
    if (ia === -1 && ib === -1) return 0;
    if (ia === -1) return 1;
    if (ib === -1) return -1;
    return ia - ib;
  });
}

// Cross-sell: products tagged to *other* moments than the current one, to
// nudge genuine discovery beyond what the customer came looking for. Festa
// items are excluded everywhere else — they read as out of place outside
// the Festa moment itself.
function pickCrossSell(momentId, alreadyShown) {
  const shownIds = alreadyShown.map((p) => p.id);
  const others = PRODUCTS.filter(
    (p) => !shownIds.includes(p.id) && !p.moments.includes(momentId) && !p.moments.includes("festa")
  );
  return others.slice(0, 2);
}

// Pulls whole numbers out of a unit string like "6, 12 ou 24 unidades" to
// offer as quantity chips. Falls back to a single default when the unit
// doesn't describe multiple options.
function parseQuantityOptions(unit) {
  const nums = (unit || "").match(/\d+/g);
  if (!nums || nums.length === 0) return [1];
  return [...new Set(nums.map((n) => parseInt(n, 10)))];
}

// Splits a total quantity evenly across N selected flavors, handing the
// remainder to the first flavors so the numbers always add up exactly.
function splitEvenly(total, count) {
  if (count === 0) return [];
  const base = Math.floor(total / count);
  const remainder = total % count;
  return Array.from({ length: count }, (_, i) => base + (i < remainder ? 1 : 0));
}

// Builds the WhatsApp message from the shared "Minha Seleção" cart, used by
// every screen (catálogo, cada momento, tela de seleção).
function buildSelectionMessage(selection) {
  const lines = selection.map((it) => {
    const head = `${it.qty ? it.qty + " " : ""}${it.name}${it.unit ? ` (${it.unit})` : ""}`;
    if (it.flavors && it.flavors.length > 0) {
      const sub = it.flavors.map((f) => `   • ${f.qty} ${f.name}`).join("\n");
      return `${head}\n${sub}`;
    }
    return head;
  });
  return `Oi! Essa é minha seleção pela Mon Caramel Collection ✨\n\n${lines.join(
    "\n\n"
  )}\n\nPodem confirmar disponibilidade, personalização e valores?`;
}

