function SendModal({ message, onClose }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(message);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {}
  };
  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div className="relative rounded-3xl max-w-md w-full p-6 sm:p-7 shadow-2xl flex flex-col fade-up" style={{ backgroundColor: "#FFFCF5", maxHeight: "85vh" }}>
        <div className="flex items-start justify-between mb-4">
          <h2 className="text-xl" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>Pronto pra enviar</h2>
          <button onClick={onClose} className="p-1.5 rounded-full hover:bg-[#F4EBDA]" aria-label="Fechar">
            <X size={20} style={{ color: COLORS.ink }} />
          </button>
        </div>
        <p className="text-sm mb-4 leading-relaxed" style={{ color: COLORS.inkSoft }}>
          Copie e nos mande pelo Instagram ou WhatsApp — a gente cuida do resto.
        </p>
        <div className="border rounded-2xl p-4 text-sm whitespace-pre-wrap overflow-y-auto flex-1 leading-relaxed" style={{ backgroundColor: "#FBF3E7", borderColor: COLORS.border, color: COLORS.ink }}>
          {message}
        </div>
        <div className="mt-5 grid grid-cols-1 sm:grid-cols-2 gap-2.5">
          <button onClick={copy} className="text-sm font-medium text-white rounded-full py-2.5 transition-transform active:scale-95 flex items-center justify-center gap-2" style={{ backgroundColor: COLORS.ink }}>
            <Copy size={14} />
            {copied ? "Copiado ✓" : "Copiar mensagem"}
          </button>
          <a href="https://instagram.com/by_moncaramel" target="_blank" rel="noreferrer" className="text-sm font-medium text-center border rounded-full py-2.5 flex items-center justify-center gap-2 hover:border-[#AB6233]" style={{ color: COLORS.ink, borderColor: "#DDD0B8" }}>
            <Instagram size={16} />
            Abrir Instagram
          </a>
        </div>
      </div>
    </div>
  );
}

