// ===========================================================================
// MOMENT RESULTS — matched products + cross-sell discovery + basket
// ===========================================================================
function MomentScreen({ momentId, onBack, onSend, favorites, toggleFavorite, onGoCatalog, selection, addToSelection, removeFromSelection, onOpenSelection }) {
  const matched = useMemo(() => pickForMoment(momentId), [momentId]);
  const crossSell = useMemo(() => pickCrossSell(momentId, matched), [momentId, matched]);
  const isFesta = momentId === "festa";
  const isPresente = momentId === "presente";
  const presenteCaixas = useMemo(() => matched.filter((p) => !p.presenteGroup || p.presenteGroup === "caixas"), [matched]);
  const presenteBandejas = useMemo(() => matched.filter((p) => p.presenteGroup === "bandejas"), [matched]);
  const presenteMimos = useMemo(() => matched.filter((p) => p.presenteGroup === "mimos"), [matched]);

  // "Minha Festa" — separate planning flow, only used inside the Festa moment.
  // Independent from the regular "Minha Seleção" basket used everywhere else.
  const [partyItems, setPartyItems] = useState([]); // [{id, name, unit, qty}]
  const [partyTheme, setPartyTheme] = useState("");
  const [partyNotes, setPartyNotes] = useState("");
  const [partyModalProduct, setPartyModalProduct] = useState(null);
  const [modalQty, setModalQty] = useState("1");
  const [modalTheme, setModalTheme] = useState("");
  const [modalNotes, setModalNotes] = useState("");
  const [toast, setToast] = useState(null);
  const partyPanelRef = useRef(null);

  const showToast = (msg) => {
    setToast(msg);
    setTimeout(() => setToast((t) => (t === msg ? null : t)), 2200);
  };

  const openPartyModal = (p) => {
    const existing = partyItems.find((it) => it.id === p.id);
    setModalQty(existing ? String(existing.qty) : "1");
    setModalTheme(partyTheme);
    setModalNotes(partyNotes);
    setPartyModalProduct(p);
  };

  const confirmPartyAdd = () => {
    const qty = Math.max(1, parseInt(modalQty, 10) || 1);
    setPartyItems((items) => {
      const exists = items.find((it) => it.id === partyModalProduct.id);
      if (exists) {
        return items.map((it) => (it.id === partyModalProduct.id ? { ...it, qty } : it));
      }
      return [...items, { id: partyModalProduct.id, name: partyModalProduct.name, unit: partyModalProduct.unit, qty }];
    });
    setPartyTheme(modalTheme);
    setPartyNotes(modalNotes);
    showToast(`✨ ${partyModalProduct.name} adicionado à Minha Festa.`);
    setPartyModalProduct(null);
  };

  const buildPartyMessage = () => {
    const lines = partyItems.map((it) => `• ${it.qty} ${it.name}`);
    let msg = `Olá! Gostaria de um orçamento para minha festa.\n\nItens selecionados:\n${lines.join("\n")}`;
    if (partyTheme.trim()) msg += `\n\nTema:\n${partyTheme.trim()}`;
    if (partyNotes.trim()) msg += `\n\nObservações:\n${partyNotes.trim()}`;
    msg += `\n\nObrigado!`;
    return msg;
  };

  const moment = MOMENTS.find((m) => m.id === momentId);

  function ProductCard({ p }) {
    const isFav = favorites.includes(p.id);
    const isCustomizable = p.customizable === true;
    const existing = selection.find((it) => it.productId === p.id);
    const [open, setOpen] = useState(false);
    const qtyOptions = useMemo(() => parseQuantityOptions(p.unit), [p.unit]);
    const [qty, setQty] = useState(existing?.qty ?? qtyOptions[0]);
    const [selectedFlavors, setSelectedFlavors] = useState(
      existing?.flavors ? existing.flavors.map((f) => f.name) : []
    );

    const toggleFlavor = (name) => {
      setSelectedFlavors((cur) => (cur.includes(name) ? cur.filter((f) => f !== name) : [...cur, name]));
    };

    const flavorBreakdown = useMemo(() => {
      if (selectedFlavors.length === 0) return [];
      const parts = splitEvenly(qty, selectedFlavors.length);
      return selectedFlavors.map((name, i) => ({ name, qty: parts[i] }));
    }, [selectedFlavors, qty]);

    const confirmAdd = () => {
      addToSelection({
        productId: p.id,
        name: p.name,
        unit: p.unit,
        qty,
        flavors: isCustomizable && flavorBreakdown.length > 0 ? flavorBreakdown : null,
      });
      setOpen(false);
    };

    return (
      <div
        className="rounded-3xl border bg-white overflow-hidden transition-all h-full flex flex-col"
        style={{ borderColor: existing ? COLORS.caramel : COLORS.border, borderWidth: existing ? "2px" : "1px" }}
      >
        <div className="relative">
          {(() => {
            const photos =
              p.photosByMoment?.[momentId] ||
              p.photos ||
              (p.photoByMoment?.[momentId] ? [p.photoByMoment[momentId]] : null) ||
              (p.photo ? [p.photo] : null) ||
              p.photoOptions ||
              null;
            return photos && photos.length > 0 ? (
              <PhotoCarousel photos={photos} alt={p.name} />
            ) : (
              <ProductArt kind={p.kind} tint={p.tint} contextIcon={MOMENT_ICON[momentId]} />
            );
          })()}
          {!isFesta && (
            <button
              onClick={() => toggleFavorite(p.id)}
              className="absolute top-3 right-3 w-8 h-8 rounded-full bg-white/90 flex items-center justify-center"
              aria-label="Guardar pra depois"
            >
              <Heart size={15} fill={isFav ? COLORS.caramel : "none"} stroke={COLORS.caramel} />
            </button>
          )}
        </div>
        <div className="p-4 flex flex-col flex-1">
          <h3 className="text-lg" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>
            {p.name}
            {!isFesta && <span className="text-xs font-normal" style={{ color: COLORS.muted }}> · {p.unit}</span>}
          </h3>
          {!isFesta && (
            <span
              className="inline-flex items-center gap-1 text-[0.65rem] font-medium rounded-full px-2 py-0.5 mt-1.5 w-fit"
              style={{
                backgroundColor: isCustomizable ? `${COLORS.gold}30` : `${COLORS.border}80`,
                color: isCustomizable ? COLORS.caramel : COLORS.muted,
              }}
            >
              {isCustomizable ? "Escolha seus sabores ✨" : "Sabor fixo"}
            </span>
          )}
          <p className="text-xs mt-1.5 leading-relaxed flex-1" style={{ color: COLORS.inkSoft }}>{p.sensory}</p>
          {isFesta ? (
            <button
              onClick={() => openPartyModal(p)}
              className="w-full mt-3 text-xs font-medium rounded-full px-3.5 py-2 flex items-center justify-center gap-1.5"
              style={{
                backgroundColor: partyItems.some((it) => it.id === p.id) ? COLORS.caramel : "transparent",
                color: partyItems.some((it) => it.id === p.id) ? "white" : COLORS.caramel,
                border: `1px solid ${COLORS.caramel}`,
              }}
            >
              🎉 {partyItems.some((it) => it.id === p.id) ? `Na minha festa (${partyItems.find((it) => it.id === p.id).qty})` : "Adicionar à Minha Festa"}
            </button>
          ) : (
            <>
              <div className="flex items-center justify-between mt-3">
                <span className="text-sm font-medium" style={{ color: COLORS.caramel }}>{p.price}</span>
                <button
                  onClick={() => (isCustomizable ? setOpen((o) => !o) : (existing ? removeFromSelection(p.id) : confirmAdd()))}
                  className="text-xs font-medium rounded-full px-3.5 py-1.5 inline-flex items-center gap-1"
                  style={{
                    backgroundColor: existing ? COLORS.caramel : "transparent",
                    color: existing ? "white" : COLORS.caramel,
                    border: `1px solid ${COLORS.caramel}`,
                  }}
                >
                  <Heart size={12} fill={existing ? "white" : "none"} />
                  {existing
                    ? isCustomizable
                      ? `Na seleção (${existing.qty})`
                      : "Adicionado ✓"
                    : isCustomizable
                    ? "Escolher sabores"
                    : "Adicionar à minha seleção"}
                </button>
              </div>

              {isCustomizable && open && (
                <div className="mt-3 pt-3" style={{ borderTop: `1px dashed ${COLORS.border}` }}>
                  {p.flavors.length === 0 ? (
                    <p className="text-xs italic" style={{ color: COLORS.muted }}>
                      Sabores em breve — fala com a gente pra combinar.
                    </p>
                  ) : (
                    <>
                      <p className="text-[0.7rem] font-medium uppercase tracking-wide mb-1.5" style={{ color: COLORS.muted }}>
                        Escolha seus sabores
                      </p>
                      <div className="flex flex-wrap gap-1.5 mb-3">
                        {p.flavors.map((f) => {
                          const on = selectedFlavors.includes(f);
                          return (
                            <button
                              key={f}
                              onClick={() => toggleFlavor(f)}
                              className="text-xs rounded-full px-2.5 py-1"
                              style={{
                                backgroundColor: on ? COLORS.caramel : "transparent",
                                color: on ? "white" : COLORS.ink,
                                border: `1px solid ${on ? COLORS.caramel : COLORS.border}`,
                              }}
                            >
                              {f}
                            </button>
                          );
                        })}
                      </div>

                      <p className="text-[0.7rem] font-medium uppercase tracking-wide mb-1.5" style={{ color: COLORS.muted }}>
                        Quantidade
                      </p>
                      <div className="flex flex-wrap gap-1.5 mb-3">
                        {qtyOptions.map((n) => (
                          <button
                            key={n}
                            onClick={() => setQty(n)}
                            className="text-xs rounded-full px-3 py-1"
                            style={{
                              backgroundColor: qty === n ? COLORS.ink : "transparent",
                              color: qty === n ? "white" : COLORS.ink,
                              border: `1px solid ${qty === n ? COLORS.ink : COLORS.border}`,
                            }}
                          >
                            {n}
                          </button>
                        ))}
                      </div>

                      {flavorBreakdown.length > 0 && (
                        <ul className="text-xs space-y-0.5 mb-3" style={{ color: COLORS.inkSoft }}>
                          {flavorBreakdown.map((f) => (
                            <li key={f.name}>• {f.qty} {f.name}</li>
                          ))}
                        </ul>
                      )}

                      <button
                        onClick={confirmAdd}
                        disabled={selectedFlavors.length === 0}
                        className="w-full text-xs font-medium rounded-full py-2 flex items-center justify-center gap-1.5"
                        style={{
                          backgroundColor: selectedFlavors.length === 0 ? COLORS.border : COLORS.caramel,
                          color: selectedFlavors.length === 0 ? COLORS.muted : "white",
                        }}
                      >
                        <Heart size={12} fill={selectedFlavors.length === 0 ? "none" : "white"} />
                        ♡ Adicionar à minha seleção
                      </button>
                    </>
                  )}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto px-6 pt-10 pb-28 fade-up">
      <BackButton onClick={onBack} label="Voltar" />

      {isPresente && (
        <div className="mt-6 mb-1">
          <p className="text-lg mb-1" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>
            Cada caixa é única.
          </p>
          <p className="text-sm" style={{ color: COLORS.inkSoft }}>
            Escolha os doces, as cores e os detalhes que combinam com quem vai receber — e a gente cria algo especial. As fotos abaixo são inspiração: nenhuma caixa sai igual à outra.
          </p>
        </div>
      )}

      {isPresente ? (
        <>
          <div
            className="flex gap-4 mt-6 overflow-x-auto snap-x snap-mandatory scroll-smooth -mx-6 px-6 pb-2"
            style={{ scrollbarWidth: "none" }}
          >
            {presenteCaixas.map((p) => (
              <div key={p.id} className="shrink-0 snap-start" style={{ width: "44%", minWidth: "150px", maxWidth: "220px" }}>
                <ProductCard p={p} />
              </div>
            ))}
          </div>

          {presenteBandejas.length > 0 && (
            <div className="mt-10">
              <div className="flex items-center gap-2 mb-1" style={{ color: COLORS.caramel }}>
                <PartyPopper size={16} />
                <span className="text-xs uppercase tracking-wide font-medium">Bandejas para Celebrar</span>
              </div>
              <p className="text-lg mb-1" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>
                Uma experiência completa, não só uma caixa.
              </p>
              <p className="text-sm mb-1" style={{ color: COLORS.inkSoft }}>
                Bandejas maiores, com balão e decoração — pra aniversário, chá de bebê, formatura ou aquela comemoração que merece mesa própria.
              </p>
              <div
                className="flex gap-4 mt-4 overflow-x-auto snap-x snap-mandatory scroll-smooth -mx-6 px-6 pb-2"
                style={{ scrollbarWidth: "none" }}
              >
                {presenteBandejas.map((p) => (
                  <div key={p.id} className="shrink-0 snap-start" style={{ width: "44%", minWidth: "150px", maxWidth: "220px" }}>
                    <ProductCard p={p} />
                  </div>
                ))}
              </div>
            </div>
          )}

          {presenteMimos.length > 0 && (
            <div className="mt-10">
              <div className="flex items-center gap-2 mb-1" style={{ color: COLORS.caramel }}>
                <Sparkles size={16} />
                <span className="text-xs uppercase tracking-wide font-medium">Mimos</span>
              </div>
              <p className="text-lg mb-1" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>
                Pequenos, mas cheios de carinho.
              </p>
              <p className="text-sm mb-1" style={{ color: COLORS.inkSoft }}>
                Mimos rápidos pra qualquer ocasião — professora, colega, agradecimento. Personalizáveis do jeitinho que você quiser.
              </p>
              <div
                className="flex gap-4 mt-4 overflow-x-auto snap-x snap-mandatory scroll-smooth -mx-6 px-6 pb-2"
                style={{ scrollbarWidth: "none" }}
              >
                {presenteMimos.map((p) => (
                  <div key={p.id} className="shrink-0 snap-start" style={{ width: "44%", minWidth: "150px", maxWidth: "220px" }}>
                    <ProductCard p={p} />
                  </div>
                ))}
              </div>
            </div>
          )}
        </>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-6">
          {matched.map((p) => <ProductCard key={p.id} p={p} />)}
        </div>
      )}

      {crossSell.length > 0 && !isPresente && momentId !== "dia-dificil" && (
        <div className="mt-9">
          <div className="flex items-center gap-2 mb-1" style={{ color: COLORS.caramel }}>
            <Sparkles size={16} />
            <span className="text-xs uppercase tracking-wide font-medium">Já que você tá por aqui...</span>
          </div>
          <p className="text-sm mb-4" style={{ color: COLORS.muted }}>Coisas que combinam com outros momentos, mas ninguém disse que era só um.</p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {crossSell.map((p) => <ProductCard key={p.id} p={p} />)}
          </div>
        </div>
      )}

      {isFesta ? (
        <div
          ref={partyPanelRef}
          className="mt-6 rounded-3xl p-5 backdrop-blur"
          style={{
            background: `linear-gradient(150deg, ${COLORS.caramel}1F, ${COLORS.gold}12)`,
            border: `1px solid ${COLORS.caramel}55`,
          }}
        >
          <p className="text-lg mb-1" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>🎉 Minha Festa</p>
          {partyItems.length === 0 ? (
            <p className="text-sm italic leading-relaxed" style={{ fontFamily: "'Cormorant Garamond', serif", color: COLORS.inkSoft }}>
              Sua festa é única. Escolha os docinhos e detalhes que mais combinam com esse momento.
            </p>
          ) : (
            <>
              <p className="text-xs uppercase tracking-wide mb-3" style={{ color: COLORS.muted }}>
                {partyItems.length} {partyItems.length === 1 ? "item adicionado" : "itens adicionados"}
              </p>
              <ul className="text-sm space-y-1.5 mb-4" style={{ color: COLORS.ink }}>
                {partyItems.map((it) => <li key={it.id}>✓ {it.name}</li>)}
              </ul>
              {partyTheme.trim() && (
                <p className="text-xs mb-1" style={{ color: COLORS.inkSoft }}><strong>Tema:</strong> {partyTheme}</p>
              )}
              {partyNotes.trim() && (
                <p className="text-xs mb-3" style={{ color: COLORS.inkSoft }}><strong>Observações:</strong> {partyNotes}</p>
              )}
              <button onClick={() => onSend(buildPartyMessage())} className="w-full text-sm font-medium text-white rounded-full py-3 flex items-center justify-center gap-2 mt-2" style={{ backgroundColor: COLORS.caramel }}>
                <MessageCircle size={15} />
                Solicitar orçamento
              </button>
            </>
          )}
        </div>
      ) : (
        selection.length > 0 && (
          <div className="mt-6 rounded-2xl border p-4 bg-white/95 backdrop-blur" style={{ borderColor: COLORS.caramel }}>
            <p className="text-xs uppercase tracking-wide mb-2" style={{ color: COLORS.muted }}>
              Você escolheu ({selection.length})
            </p>
            <button onClick={onOpenSelection} className="w-full text-sm font-medium text-white rounded-full py-3 flex items-center justify-center gap-2" style={{ backgroundColor: COLORS.caramel }}>
              <Heart size={15} />
              Ver Minha Seleção
            </button>
          </div>
        )
      )}

      {partyModalProduct && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-6" onClick={() => setPartyModalProduct(null)}>
          <div className="bg-white rounded-3xl p-6 max-w-sm w-full" onClick={(e) => e.stopPropagation()}>
            <p className="text-lg mb-4" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>🎉 {partyModalProduct.name}</p>

            <label className="text-xs font-medium block mb-1" style={{ color: COLORS.muted }}>Quantidade desejada</label>
            <input
              type="number"
              min="1"
              value={modalQty}
              onChange={(e) => setModalQty(e.target.value)}
              className="w-full rounded-xl border px-3 py-2 mb-4 text-sm"
              style={{ borderColor: COLORS.border }}
            />

            <label className="text-xs font-medium block mb-1" style={{ color: COLORS.muted }}>Tema da festa (opcional)</label>
            <input
              type="text"
              value={modalTheme}
              onChange={(e) => setModalTheme(e.target.value)}
              placeholder="Ex: Safari, Moana, tons verde e dourado..."
              className="w-full rounded-xl border px-3 py-2 mb-4 text-sm"
              style={{ borderColor: COLORS.border }}
            />

            <label className="text-xs font-medium block mb-1" style={{ color: COLORS.muted }}>Observações (opcional)</label>
            <textarea
              value={modalNotes}
              onChange={(e) => setModalNotes(e.target.value)}
              placeholder="Alguma preferência de cor, sabor ou detalhe especial?"
              className="w-full rounded-xl border px-3 py-2 mb-5 text-sm"
              rows={3}
              style={{ borderColor: COLORS.border }}
            />

            <div className="flex gap-2">
              <button onClick={() => setPartyModalProduct(null)} className="flex-1 text-sm rounded-full py-2.5" style={{ color: COLORS.muted, border: `1px solid ${COLORS.border}` }}>
                Cancelar
              </button>
              <button onClick={confirmPartyAdd} className="flex-1 text-sm font-medium text-white rounded-full py-2.5" style={{ backgroundColor: COLORS.caramel }}>
                Adicionar
              </button>
            </div>
          </div>
        </div>
      )}

      <button
        onClick={onGoCatalog}
        className="w-full text-center text-xs mt-8 py-2 underline"
        style={{ color: COLORS.muted }}
      >
        Não encontrou o que imaginava? Explore toda a coleção.
      </button>

      {isFesta && partyItems.length > 0 && (
        <button
          onClick={() => partyPanelRef.current?.scrollIntoView({ behavior: "smooth", block: "center" })}
          className="fixed bottom-6 right-6 z-40 rounded-full px-5 py-3 text-sm font-medium text-white flex items-center gap-2 shadow-lg"
          style={{ backgroundColor: COLORS.caramel }}
        >
          🎉 Minha Festa ({partyItems.length})
        </button>
      )}

      {toast && (
        <div
          className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 text-sm text-white rounded-full px-4 py-2.5 shadow-lg"
          style={{ backgroundColor: COLORS.ink }}
        >
          {toast}
        </div>
      )}
    </div>
  );
}

// ===========================================================================
// ROOT
// ===========================================================================
// ===========================================================================
// MINHA SELEÇÃO — shared wishlist/order-builder, filled in from every screen,
// finalized as one WhatsApp message.
// ===========================================================================
function SelectionScreen({ selection, removeFromSelection, onBack, onSend }) {
  return (
    <div className="max-w-2xl mx-auto px-6 pt-10 pb-28 fade-up">
      <BackButton onClick={onBack} label="Continuar escolhendo" />
      <h2 className="text-2xl mb-1" style={{ fontFamily: FONT_DISPLAY, color: COLORS.ink }}>♡ Minha Seleção</h2>
      <p className="text-sm mb-6" style={{ color: COLORS.muted }}>
        {selection.length === 0
          ? "Ainda vazia — volte e escolha o que combinar com o momento."
          : "Confira tudo antes de enviar pra gente combinar os detalhes."}
      </p>

      {selection.length === 0 ? (
        <button
          onClick={onBack}
          className="w-full text-sm font-medium rounded-full py-3"
          style={{ color: COLORS.caramel, border: `1px solid ${COLORS.caramel}` }}
        >
          Explorar a coleção
        </button>
      ) : (
        <>
          <div className="space-y-3 mb-6">
            {selection.map((it) => (
              <div key={it.productId} className="rounded-2xl border bg-white p-4" style={{ borderColor: COLORS.border }}>
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p style={{ fontFamily: FONT_DISPLAY, fontSize: "1.05rem", color: COLORS.ink }}>
                      {it.qty} {it.name}
                    </p>
                    {!it.flavors && <p className="text-xs mt-0.5" style={{ color: COLORS.muted }}>{it.unit}</p>}
                    {it.flavors && (
                      <ul className="text-xs mt-1.5 space-y-0.5" style={{ color: COLORS.inkSoft }}>
                        {it.flavors.map((f) => (
                          <li key={f.name}>• {f.qty} {f.name}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                  <button
                    onClick={() => removeFromSelection(it.productId)}
                    className="w-7 h-7 rounded-full flex items-center justify-center shrink-0"
                    style={{ color: COLORS.muted, border: `1px solid ${COLORS.border}` }}
                    aria-label="Remover"
                  >
                    <X size={13} />
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="flex flex-col gap-2">
            <button
              onClick={() => onSend(buildSelectionMessage(selection))}
              className="w-full text-sm font-medium text-white rounded-full py-3 flex items-center justify-center gap-2"
              style={{ backgroundColor: COLORS.caramel }}
            >
              <MessageCircle size={15} />
              Finalizar pelo WhatsApp
            </button>
            <button onClick={onBack} className="w-full text-sm rounded-full py-3" style={{ color: COLORS.muted }}>
              Continuar escolhendo
            </button>
          </div>
        </>
      )}
    </div>
  );
}

// ===========================================================================
// ROOT
// ===========================================================================
export default function MonCaramelCollection() {
  const [screen, setScreen] = useState(null); // null = home, "catalogo", "selecao", or a moment id
  const [pendingMessage, setPendingMessage] = useState(null);
  const [favorites, setFavorites] = useState([]);
  const [selection, setSelection] = useState([]); // [{productId, name, unit, qty, flavors: [{name, qty}] | null}]

  const toggleFavorite = (id) => setFavorites((f) => (f.includes(id) ? f.filter((x) => x !== id) : [...f, id]));

  // One entry per product: adding again (e.g. re-configuring flavors) updates
  // it in place instead of duplicating the line.
  const addToSelection = (entry) => {
    setSelection((s) => {
      const exists = s.some((it) => it.productId === entry.productId);
      if (exists) return s.map((it) => (it.productId === entry.productId ? { ...it, ...entry } : it));
      return [...s, entry];
    });
  };
  const removeFromSelection = (productId) => setSelection((s) => s.filter((it) => it.productId !== productId));

  const onGoSelection = () => setScreen("selecao");

  return (
    <div className="min-h-screen" style={{ backgroundColor: COLORS.cream, fontFamily: "'Roboto', sans-serif" }}>
      <GlobalStyle />
      {!screen && <HomeScreen onSelect={setScreen} favorites={favorites} />}
      {screen === "catalogo" && (
        <CatalogScreen
          onBack={() => setScreen(null)}
          onSend={setPendingMessage}
          favorites={favorites}
          toggleFavorite={toggleFavorite}
          selection={selection}
          addToSelection={addToSelection}
          onOpenSelection={onGoSelection}
        />
      )}
      {screen === "selecao" && (
        <SelectionScreen
          selection={selection}
          removeFromSelection={removeFromSelection}
          onBack={() => setScreen(null)}
          onSend={setPendingMessage}
        />
      )}
      {screen && screen !== "catalogo" && screen !== "selecao" && (
        <MomentScreen
          momentId={screen}
          onBack={() => setScreen(null)}
          onGoCatalog={() => setScreen("catalogo")}
          onSend={setPendingMessage}
          favorites={favorites}
          toggleFavorite={toggleFavorite}
          selection={selection}
          addToSelection={addToSelection}
          removeFromSelection={removeFromSelection}
          onOpenSelection={onGoSelection}
        />
      )}

      {selection.length > 0 && screen !== "selecao" && (
        <button
          onClick={onGoSelection}
          className="fixed bottom-6 left-6 z-40 rounded-full px-5 py-3 text-sm font-medium text-white flex items-center gap-2 shadow-lg"
          style={{ backgroundColor: COLORS.caramel }}
        >
          <Heart size={15} fill="white" />
          Minha Seleção ({selection.length})
        </button>
      )}

      {pendingMessage && <SendModal message={pendingMessage} onClose={() => setPendingMessage(null)} />}
    </div>
  );
}
